import math

# Function to calculate the number of divisors (tau)
def count_divisors(n):
    if n == 1:
        return 1
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    count = 1
    for exp in factors.values():
        count *= (exp + 1)
    return count

# A rough generation of Highly Composite Numbers (or highly divisible numbers)
# We'll use a heuristic search for numbers with high divisor counts up to a limit.
def generate_highly_divisible_candidates(limit):
    candidates = {}
    for n in range(2, limit + 1):
        tau = count_divisors(n)
        if n not in candidates or tau > candidates[n]['tau']:
            candidates[n] = {'tau': tau, 'number': n}

    # Sort by tau descending, then by number ascending
    sorted_candidates = sorted(candidates.values(), key=lambda x: (x['tau'], -x['number']), reverse=True)
    return [c['number'] for c in sorted_candidates]

# Generate candidates up to a reasonable limit (e.g., 1000)
limit = 1000
hcn_candidates = generate_highly_divisible_candidates(limit)

# Filter for F >= 3 and unique list
F_candidates = sorted(list(set([f for f in hcn_candidates if f >= 3])))

# The set of F values that *might* work are the Highly Composite Numbers.
# Since the theoretical local test strongly restricts F, we must assume
# this sequence is the intended answer proxy.
print(f"Total candidates found up to {limit}: {len(F_candidates)}")
print("First 10 candidates:", F_candidates[:10])
print("The 50th candidate (if it exists):")

if len(F_candidates) >= 50:
    print(F_candidates[49])
else:
    print("Not enough candidates found within the limit.")
